local Catalog = {}

Catalog.overrides = {}

Catalog.creatures = {
    -- Level 101
    { template_id = "bloody_halfling_cannibal", name = "bloody halfling cannibal", level = 101, spawn_areas = { "Hinterwilds" }, roam_areas = { "Hinterwilds" }, family = "humanoid", body_type = "biped", hp = 170, hp_variance = 17, td = 428, armor_asg = 12, armor_natural = false, preferred_stance = "forward", stance_profile = "berserker", description = "A skim of dark, congealing blood slicks the features of the raw-boned halfling. Her eyes are black as burnt coals and feverish with single-minded hunger, a hunger that has burnt away every last shred of fat from her body and left behind only knotted sinew. The cannibal's teeth are sharpened to jagged points, and from between them darts a tiny pink tongue that is constantly tasting the air. She wears tattered, weather-eaten remains of furs and homespun fabric. They, too, are soaked red with blood.", attacks = { { type = "wiry_arms" } } },
    { template_id = "cadaverous_tatterdemalion_ghast", name = "cadaverous tatterdemalion ghast", level = 101, spawn_areas = { "Moonsedge" }, roam_areas = { "Moonsedge" }, family = "humanoid", classification = "corporeal_undead", body_type = "biped", hp = 325, hp_variance = 32, td = 453, armor_asg = 5, armor_natural = false, preferred_stance = "forward", stance_profile = "berserker", description = "Clad in the dilapidated remains of homespun clothing, the ghast's form is only passingly humanoid. Death has transformed his features, filming over his eyes and leaving him with only a sloughing remnant of a nose. His hind legs are powerfully muscled, but his hands have atrophied into long talons that are unsettlingly spare of flesh. He is a scabrous and unwholesome beast, and the smear of dried blood and effluvia around his mouth hints at distasteful appetites. Appraisal: The tatterdemalion ghast is medium in size and about five feet high in her current state.", attacks = { { type = "claw_attack" }, { type = "pound_attack" } }, abilities = { "tackle" } },

    -- Level 102
    { template_id = "chitinous_kiramon_myrmidon", name = "chitinous kiramon myrmidon", level = 102, spawn_areas = { "The Hive" }, roam_areas = { "The Hive" }, family = "kiramon", body_type = "insectoid", hp = 500, hp_variance = 50, armor_asg = 20, armor_natural = true, preferred_stance = "offensive", stance_profile = "skirmisher", description = "The myrmidon's chitin is a cold and lustrous black, infused with an oil slick of darkly rainbowed colors that are almost hypnotically beautiful to behold. Clusters of barbed spines protrude from the upper segments of his spindly arms, each of which ends in a sharp scythe-like claw. Above a set of oversized, prehensile mandibles, the kiramon myrmidon's orb-shaped eyes are a sullen red and are faceted like pristine rubies. They are possessed of an intellect that is as vast as it is otherworldly.", attacks = { { type = "bite" }, { type = "pincer_attack" } }, abilities = { "taunt", "powerful_blow" } },
    { template_id = "flickering_mist_wreathed_banshee", base_template = "fallen_crusader", name = "flickering mist-wreathed banshee", level = 102, spawn_areas = { "Moonsedge" }, roam_areas = { "Moonsedge" }, family = "ghost", classification = "non_corporeal_undead", body_type = "biped", hp = 300, hp_variance = 30, td = 517, armor_asg = 1, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "Mists pirouette about the tattered hem of the mist-wreathed banshee's gown so that it is unclear where the garment ends and they begin. Though there are the remnants of loveliness to her visage, the banshee's cheeks are sunken and her eyes are empty chasms of shadow. Dark hair, wild and unkempt, swirls around her face as if constantly blown by a howling breeze. The banshee's form is barely substantial and light filters grimly through her. Appraisal: The mist-wreathed banshee is medium in size and about five feet high in her current state." },
    { template_id = "heavily_armored_battle_mastodon", base_template = "wooly_mammoth", name = "heavily armored battle mastodon", level = 102, spawn_areas = { "Hinterwilds" }, roam_areas = { "Hinterwilds" }, family = "elephantid", body_type = "quadruped", td = 480, armor_asg = 1, armor_natural = false, preferred_stance = "offensive", stance_profile = "skirmisher", description = "Heavy plates of copper barding shield the flanks of the immense mastodon, a woolly beast covered in dark, matted hair. The mastodon's eyes are dark, round, and surprisingly expressive. To either side of its long, prehensile trunk are curved tusks that taper to deadly points. The yellowed bones have been delicately etched with carved runes.", attacks = { { type = "trunk_slam" }, { type = "tusk_spear" } } },
    { template_id = "immense_gold_bristled_hinterboar", name = "immense gold-bristled hinterboar", level = 102, spawn_areas = { "Hinterwilds" }, roam_areas = { "Hinterwilds" }, family = "suine", body_type = "quadruped", hp = 400, hp_variance = 40, td = 467, armor_asg = 1, armor_natural = false, preferred_stance = "offensive", stance_profile = "skirmisher", description = "Squinty eyes the color of molten copper dart here and there as if the immense boar is always on the alert for predators, but given its tremendous mass, it likely has little cause for worry. The hinterboar's pelt is a glittering, metallic golden in hue, but is shot through with a hypnotic pattern of duskier bristles. The line of raised bristles down the center of the beast's spine seems to radiate faint luminescence, warm and honey-hued.", attacks = { { type = "stomp" }, { type = "impale" } }, abilities = { "charge_knockdown" } },
    { template_id = "ithzir_champion", name = "ithzir champion", level = 102, spawn_areas = { "Old Ta'Faendryl" }, roam_areas = { "Old Ta'Faendryl" }, family = "ithzir", classification = "extra_planar", body_type = "biped", hp = 300, hp_variance = 30, ds_melee = 304, ds_ranged = 342, ds_bolt = 370, td = 466, armor_asg = 17, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "__NOTOC__ With a competely tattooed forehead and hands, the champion bears an imperious, domineering presence. Muscular and athletic, the Ithzir champion is a full head taller than the average man, and her light-blue skin is completely hairless. Exuding an air of calm and in control, she appears dangerous and fearsome in any situation - and while she seems mostly humanoid, strange proportions and awkward construction make her alien and unknownable. The champion wears a well made royal blue tunic, with the image of a rearing griffin emblazoned in gold thread on the right breast.", attacks = { { type = "flamberge" }, { type = "maul" } }, spells = { "Arm of the Arkati" }, abilities = { "disarm_weapon", "charge_knockdown", "spirit_warding_i_101", "spirit_defense_103", "mantle_of_faith_1601" }, immune = { "stun" } },
    { template_id = "pale_scaled_shaper", name = "pale scaled shaper", level = 102, spawn_areas = { "Sanctum" }, roam_areas = { "Sanctum" }, family = "humanoid", body_type = "biped", hp = 265, hp_variance = 26, ds_melee = 555, ds_ranged = 616, td = 368, armor_asg = 1, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "A pale scaled shaper is far taller than a woman ought to be, with a stretched appearance like that of a doll tugged by battling children. That is, if she is even female: the pale robes that she wears, with their faint appliqued patterns of winking copper scales, betray only the most suggestive promise of a feminine form beneath. There is something upsettingly inhuman about the shaper's face, which has the shape and proportions of a human's, but eyes that glow like green embers and a dusting of ridged scales on its cheeks and brow.", spells = { "Disintegrate", "Cloak of Shadows", "Spiritual Abolition", "Condemn" }, abilities = { "fire_bolt", "gas_cloud", "tremors", "spirit_warding_i_101", "lesser_shroud_120", "spirit_shield_202", "bravery_211" } },
    { template_id = "triton_magus", base_template = "triton_fanatic", name = "triton magus", level = 102, spawn_areas = { "Ruined Temple" }, roam_areas = { "Ruined Temple" }, family = "triton", body_type = "biped", ds_melee = 443, td = 373, armor_asg = 8, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "Moving quietly on wide, webbed feet, the triton magus seems to slip between the shadows, her damp mottled flesh shifting colors with the surroundings. The creature pauses frequently, her flared nostrils quivering as if seeking beings as nearly invisible as herself. A long row of tiny needle-sharp teeth protrudes from grey gums, visible behind her curled, wet lips. A loose robe in varying shades of grey and green covers the magus, hanging just below her twitching tail.", attacks = { { type = "arrow" } }, spells = { "Nature's Fury" }, abilities = { "elemental_targeting_425", "taunt", "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414", "natural_colors_601", "resist_elements_602", "self_control_613", "spirit_defense_103" } },
    { template_id = "triton_warden", name = "triton warden", level = 102, spawn_areas = { "Atoll" }, roam_areas = { "Atoll" }, family = "triton", body_type = "biped", hp = 300, hp_variance = 30, td = 480, armor_asg = 12, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "A faded coat of sun-bleached oilskin graces the muscular shoulders of a triton warden, the rusted ornamentations covered in grey-cast barnacles and dried kelp. His trident-branded knuckles are exposed through his desiccated leather gloves, the shreds of hide clinging tightly to his green-tinged forearms. The warden growls softly through his clenched teeth, the sharp protrusions biting down on a broken driftwood pipe.", attacks = { { type = "longbow" } }, spells = { "Wild Entropy" }, abilities = { "spirit_warding_i_101", "spirit_defense_103", "natural_colors_601", "resist_elements_602", "self_control_613" } },

    -- Level 103
    { template_id = "enormous_rift_crawler", name = "enormous rift crawler", level = 103, spawn_areas = { "The Rift" }, roam_areas = { "The Rift" }, family = "worm", classification = "extra_planar", body_type = "ophidian", hp = 400, hp_variance = 40, ds_melee = 483, td = 442, armor_asg = 12, armor_natural = true, preferred_stance = "offensive", stance_profile = "skirmisher", description = "This creature's monstrous form has the appearance of liquid, distorted glass overlying a fog-swamped night. Its outer flesh is translucent and glossy, run through with thready veins of black and purple. Beneath, the creature seems to have a secondary skin of darkest grey. Not scaled, but segmented, the body within its vitreous shell undulates in a way only smoke can. It roils and shifts as though it were an insubstantial core within a confining barrier. Its maw is a gaping round of ring upon ring of jagged, obsidian-like teeth.", attacks = { { type = "bite" }, { type = "charge_attack" } }, abilities = { "hide" } },
    { template_id = "ethereal_triton_psionicist", name = "ethereal triton psionicist", level = 103, spawn_areas = { "Atoll" }, roam_areas = { "Atoll" }, family = "triton", classification = "non_corporeal_undead", body_type = "biped", hp = 240, hp_variance = 24, td = 498, armor_asg = 11, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "An ethereal triton psionicist scowls about the area, her unsubstantial bluish skin rippling like waves across the ocean. Her tongue flickers out, pierced by a tiny atoll crab, and barnacles encircle each muscular arm. Sigil-carved shell rings adorn each finger, and a broken ivory trident dangles from an intangible coral belt.", attacks = { { type = "unarmed_combat" } }, spells = { "Telekinesis", "Astral Spear", "Thought Lash", "Vertigo", "Mindwipe", "Mana Burst" }, abilities = { "iron_skin_1202", "blink_1215" } },
    { template_id = "ethereal_triton_sentry", base_template = "spectral_triton_defender", name = "ethereal triton sentry", level = 103, spawn_areas = { "Ruined Temple" }, roam_areas = { "Ruined Temple" }, family = "triton", classification = "non_corporeal_undead", body_type = "biped", preferred_stance = "guarded", stance_profile = "caster", description = "The triton sentry holds himself erect, as he skims along the ground on long-nailed translucent webbed feet. Obsessively alert, the creature sniffs constantly and halts to listen every few moments. Despite empty eye sockets, constantly weeping viscous green mucus, he peers into the shadows for infiltrators, his head constantly turning with rapid, jerky motions. Threadbare green-belted robes cover his insubstantial frame.", spells = { "Dark Catalyst", "Mana Disruption", "Disintegrate", "Mind Jolt", "Implosion" }, abilities = { "tremors" } },
    { template_id = "smouldering_skeletal_dreadsteed", name = "smouldering skeletal dreadsteed", level = 103, spawn_areas = { "Moonsedge" }, roam_areas = { "Moonsedge" }, family = "equine", classification = "corporeal_undead", body_type = "quadruped", hp = 500, hp_variance = 50, td = 447, armor_asg = 15, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "Clad in fatigued barding, the skeletal dreadsteed is an ossified vestige of a powerful steed. Bits of dried flesh cling to the bones, but its ribcage is an open ruin that holds a twisting, nebulous orb of phantasmal blue flame. More cerulean fire sprouts from its skull, neck, and hinquarters as an unearthly mane and tail. Its bony hooves are shod in old steel. Appraisal: The skeletal dreadsteed is large in size and about five feet high in its current state.", attacks = { { type = "bite_attack" }, { type = "charge_attack" }, { type = "stomp_attack" } }, spells = { "Flaming Aura" }, abilities = { "taunt", "powerful_blow", "charge_knockdown" } },
    { template_id = "stunted_halfling_bloodspeaker", name = "stunted halfling bloodspeaker", level = 103, spawn_areas = { "Hinterwilds" }, roam_areas = { "Hinterwilds" }, family = "humanoid", body_type = "biped", hp = 360, hp_variance = 36, td = 537, armor_asg = 2, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "Small even for a halfling, the bloodspeaker is twisted of limb and stunted of form. Bulging eyes the color of dried blood peer out from a face like molten wax. The ritualistic burn scars marring his flesh look painful beyond the most grotesque of imaginings. The bloodspeaker wears heavy robes of red velvet that do little to conceal the broken-puppet jangle of his misshapen body beneath them. His tongue is bisected and lolls forth from a mouth that looks like a wet gash in his obscene face.", attacks = { { type = "runestaff" } }, spells = { "Bone Shatter", "Corrupt Essence", "Wither" } },
    { template_id = "tattooed_gigas_berserker", base_template = "triton_brawler", name = "tattooed gigas berserker", level = 103, spawn_areas = { "Hinterwilds" }, roam_areas = { "Hinterwilds" }, family = "gigas", body_type = "biped", td = 462, armor_asg = 10, armor_natural = false, preferred_stance = "forward", stance_profile = "berserker", description = "A tattooed gigas berserker is a hulking brute of a gigas, standing more than four times the height of a man and with the immense muscle mass to match. His vast biceps are ringed with intricate tattoos in auroral colors: glacial blues and flashfire greens that are bright enough to have been stolen from cut jewels. The rest of him is unlovely, from his matted beard to the look of murder in his bulging eyes.", attacks = { { type = "hatchet" } } },

    -- Level 104
    { template_id = "behemothic_gorefrost_golem", name = "behemothic gorefrost golem", level = 104, spawn_areas = { "Hinterwilds" }, roam_areas = { "Hinterwilds" }, family = "golem", body_type = "biped", hp = 1000, hp_variance = 100, td = 457, armor_asg = 20, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "The golem stands taller than a two-story building, a crude and blocky humanoid shape of ice that glows with an unsavory sanguine aura. Clouds of frozen blood and bits of viscera are trapped in its frosty depths. All are lifeless and still save for a single preserved organ at the golem's core: a humanoid heart. The heart is shrouded in a swirl of slushy red fluid and, impossibly, it pulses with a sluggish, uneven beat, giving off coruscations of sanguine light.", attacks = { { type = "stomp" }, { type = "pound" }, { type = "closed_fist" } }, spells = { "Cold Snap" }, abilities = { "cold_flare", "tremors", "powerful_blow" } },
    { template_id = "brackish_bilge_mass", base_template = "war_griffin", name = "brackish bilge mass", level = 104, spawn_areas = { "Ship Graveyard" }, roam_areas = { "Ship Graveyard" }, body_type = "hybrid", preferred_stance = "forward", stance_profile = "berserker", description = "==Hunting Strategies== *" },
    { template_id = "darkly_inked_fetish_master", base_template = "athletic_dark_eyed_incubus", name = "darkly inked fetish master", level = 104, spawn_areas = { "Scatter" }, roam_areas = { "Scatter" }, family = "humanoid", classification = "extra_planar", body_type = "biped", ds_ranged = 488, ds_bolt = 388, td = 495, preferred_stance = "guarded", stance_profile = "caster", description = "__NOTOC__ A 'darkly inked fetish master' can be found in the Scatter in the Rift. This creature is a child-like voodoo witch doctor, drawing upon elaborate inked designs on its skin for its dark powers. The masters cast mostly Sorcerer spells and can summon a cluster of wooden dolls on their current target, who would lay down a barrage of attacks. Dark-ringed eyes stare out of a face that is gaunt and ashen as a darkly inked fetish master looks on. Beginning at its hairline, a labyrinthine pattern of tattoos in ebon ink crawl across the fetish master's skin, spanning brow and cheeks alike. The designs sheath every inch of exposed skin not shrouded beneath its tattered robes. In a grotesque display, the fetish master's lips have been peeled back from its gums, secured in place by a set of discolored hooks. Perhaps not the intention, but the effect creates a perpetual, toothy grin that seems to hold no amusement, but ample amounts of malice.", spells = { "Silence", "Unbalance" }, abilities = { "sonic_wail", "tail_spike_volley" } },
    { template_id = "disfigured_hive_thrall", name = "disfigured hive thrall", level = 104, spawn_areas = { "The Hive" }, roam_areas = { "The Hive" }, family = "humanoid", body_type = "biped", hp = 375, hp_variance = 37, armor_asg = 6, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "The thrall looks to have once been humanoid, but her form has been mutilated into a tortured, stooped shape with a mismatch of clashing parts. One eye is huge and insectoid, but the other remains painfully close to mammalian, its pupil bleeding into the bright green iris. Her jaw hangs slack, forced open at all times by a set of bristled mandibles that seem to have a mind of their own as they twitch and clench. Tumorous growths stud the thrall's spine, unsavory green where they are not blotchy violet-red with pustules. One has burst to reveal a single rudimentary wing that resembles a fly's.", attacks = { { type = "charge" }, { type = "claw" } }, spells = { "Major Acid", "Web bolt", "Wild Entropy", "Powersink" }, abilities = { "charge_knockdown", "iron_skin_1202" } },
    { template_id = "infernal_death_knight", base_template = "death_dirge", name = "infernal death knight", level = 104, spawn_areas = { "Moonsedge" }, roam_areas = { "Moonsedge" }, family = "humanoid", classification = "corporeal_undead", body_type = "biped", hp = 500, hp_variance = 50, td = 426, armor_asg = 19, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "Judging from her height, the death knight is a mummified remnant of a powerful warrior, though the flesh has mostly come free from her animated bones. Now, her heavy armor is all that holds her skeletal form together. Her neck ends in a jagged ruin, but over the shattered fragments of her spine hovers a bleached skull that is wreathed in azure flames. Fires burn malevolently in the skull's empty sockets. Appraisal: The death knight is medium in size and about seven feet high in her current state." },
    { template_id = "niveous_giant_warg", base_template = "crazed_canine", name = "niveous giant warg", level = 104, spawn_areas = { "Hinterwilds" }, roam_areas = { "Hinterwilds" }, family = "canine", body_type = "quadruped", td = 410, armor_asg = 1, armor_natural = false, preferred_stance = "offensive", stance_profile = "skirmisher", description = "Larger than a draft horse, the warg is the apotheosis of predatory instinct and lupine form. With a heavy coat the color of freshly driven snow and a thick mane agleam with frost crystals in glittering blues and glacial greens, the warg is as beautiful as it is murderous. The beast's eyes are cold aquamarine and faintly lambent, shining with ferocious intellect.", attacks = { { type = "bite" } } },

    -- Level 105
    { template_id = "greater_water_elemental", base_template = "water_elemental", name = "greater water elemental", level = 105, spawn_areas = { "Ruined Temple" }, roam_areas = { "Ruined Temple" }, family = "elemental", classification = "magical", body_type = "hybrid", ds_melee = 348, td = 534, preferred_stance = "forward", stance_profile = "berserker", description = "The water elemental's upper body is that of a humanoid, while its lower body forms a turbulent, watery vortex. The facial features of the elemental creature are vague and shifting, rippling with every contortion of its face. Sloshing and splashing noises accompany each movement of the water elemental, along with an odd gurgling.", attacks = { { type = "pound" } }, spells = { "Elemental Strike", "Elemental Disjunction" }, abilities = { "water_bolt", "tremors", "elemental_defense_i_401", "elemental_defense_ii_406", "elemental_defense_iii_414", "elemental_targeting_425", "elemental_barrier_430", "elemental_bias_508", "spirit_shield_202" } },
    { template_id = "grim_gigas_skald", base_template = "triton_fanatic", name = "grim gigas skald", level = 105, spawn_areas = { "Hinterwilds" }, roam_areas = { "Hinterwilds" }, family = "gigas", body_type = "biped", td = 469, armor_asg = 6, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "A grim gigas skald is not especially tall for one of her kind, but still stands just under two stories tall. She has a raw-boned face and a grim gaze. The robes she wears are of dusky golden boarskin and appear ceremonial, having been stitched with hundreds of beads made from semiprecious gems. A grim gigas skald wears a tremendous drinking horn at her belt.", spells = { "Stunning Shout" }, abilities = { "lesser_shroud_120", "resist_elements_602" } },
    { template_id = "hapless_charmed_corsair", base_template = "deathsworn_fanatic", name = "hapless charmed corsair", level = 105, spawn_areas = { "Singing Crags" }, roam_areas = { "Singing Crags" }, family = "humanoid", body_type = "biped", preferred_stance = "guarded", stance_profile = "caster", description = "==Hunting Strategies== *" },
    { template_id = "horned_basalt_grotesque", name = "horned basalt grotesque", level = 105, spawn_areas = { "Moonsedge" }, roam_areas = { "Moonsedge" }, family = "golem", body_type = "biped", hp = 750, hp_variance = 75, ds_melee = 518, ds_bolt = 429, td = 522, armor_asg = 20, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "Huge and hulking, the basalt grotesque is an imposing figure cut from black basalt. Roughly humanoid in shape though not in particulars, the grotesque has a bestial visage. The carved musculature of its back joins with two great wings that span wider than it is tall. From its head sprouts a quintet of rounded horns. Its eyes, a burning green, match the hue of a viridian soulstone embedded into the rock of its broad chest. Appraisal: The basalt grotesque is large in size, about eight feet high in its current state, appears to be of exceptionally hardy constitution, is in a guarded stance, and is in relatively good shape.", attacks = { { type = "closed_fist" }, { type = "stomp" }, { type = "bite" } }, spells = { "Hurl Boulder", "Stone Fist" }, abilities = { "tremors", "call_wind", "earthen_fury_caster" } },
    { template_id = "savage_fork_tongued_wendigo", name = "savage fork-tongued wendigo", level = 105, spawn_areas = { "Hinterwilds" }, roam_areas = { "Hinterwilds" }, family = "humanoid", body_type = "biped", hp = 600, hp_variance = 60, td = 489, armor_asg = 10, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "The wendigo looks to have once been humanoid. Magics have contorted and stretched its form into an atrocity of exposed bone and raw tissues that stands several heads taller than a giantman. Sprouting antlers of bloodstained bone breach up from the sparse flesh of the wendigo's skull. Its eyes are misty pools of light that cast the rest of the wendigo's face in haunted shadow. The abomination's maw is forced open by multifarious rows of shark-like teeth, but its tongue is forked like that of a snake.", attacks = { { type = "claw_attack" }, { type = "bite_attack" } }, spells = { "CS" } },

    -- Level 106
    { template_id = "brawny_gigas_shield_maiden", base_template = "triton_fanatic", name = "brawny gigas shield-maiden", level = 106, spawn_areas = { "Hinterwilds" }, roam_areas = { "Hinterwilds" }, family = "gigas", body_type = "biped", td = 462, armor_asg = 17, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "Voluptuous and sturdy of build, the gigas shield-maiden has the musculature of a seasoned fighter and the cool gaze of a practiced tactician. Towering at nearly thirty feet in height, the shield-maiden moves with a dangerous grace. The armor she wears is not ornate, but it shines like hammered gold and barely makes a sound as she moves.", attacks = { { type = "spear" } }, spells = { "Aura of the Arkati", "Judgment" } },
    { template_id = "corpulent_kresh_ravager", base_template = "kiramon_worker", name = "corpulent kresh ravager", level = 106, spawn_areas = { "The Hive" }, roam_areas = { "The Hive" }, family = "kiramon", body_type = "insectoid", hp = 750, hp_variance = 75, armor_asg = 8, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "Hugely bloated, the abdomen of the kresh ravager is fleshy and sickly white-yellow. It jiggles as the ravager skitters around on undersized legs that, while thin and short, appear to possess enough strength to support the ticklike monstrosity's great bulk. By contrast, the ravager's forelegs are powerful and armored in a glittering substance that resembles diamond. Comically undersized mandibles frame its small mouth, which constantly drips an unsavory yellow-green ichor." },
    { template_id = "gaudy_phantasmic_conjurer", base_template = "fallen_crusader", name = "gaudy phantasmic conjurer", level = 106, spawn_areas = { "Moonsedge" }, roam_areas = { "Moonsedge" }, family = "ghost", classification = "non_corporeal_undead", body_type = "biped", hp = 325, hp_variance = 32, td = 574, armor_asg = 1, armor_natural = true, preferred_stance = "forward", stance_profile = "berserker", description = "==Description== A pale, silver-blue aura wavers around the phantasmic conjurer's form, muting the hues of his brightly colored robes. Though insubstantial, the garments' hues are a loud clash of vibrant reds and strident greys. On his head, he wears a jaunty cap adorned with a flagrant white plume. The conjurer's ghostly form is uninjured save for a jagged line across his neck. Appraisal: The phantasmic conjurer is medium in size and about five feet high in her current state.", spells = { "458 CS" }, abilities = { "prismatic_guard_905" } },
    { template_id = "milky_eyed_drowned_mariner", base_template = "deathsworn_fanatic", name = "milky-eyed drowned mariner", level = 106, spawn_areas = { "Ship Graveyard" }, roam_areas = { "Ship Graveyard" }, family = "humanoid", body_type = "hybrid", preferred_stance = "guarded", stance_profile = "caster", description = "==Hunting Strategies== *" },
    { template_id = "murky_soul_siphon", base_template = "soul_golem", name = "murky soul siphon", level = 106, spawn_areas = { "Scatter" }, roam_areas = { "Scatter" }, family = "siphon", classification = "corporeal_undead", body_type = "biped", ds_bolt = 349, td = 482, preferred_stance = "guarded", stance_profile = "caster", description = "__NOTOC__ A 'murky soul siphon' can be found in the Scatter in the Rift. This is an undead entity subsisting upon the souls of the living. Classified as a semi, it uses various debuff spells to set up its foes for easier consumption. Its attacks have a chance to drain spirit and they also make use of a maneuver-based grasp to suck spirit from characters. Though it has a vaguely humanoid shape, the soul siphon is unlike anything that inhabits the walking world -- rather, it resembles something that escaped from the fevered nightmares of the deranged. Completely hairless, its skin is a dirty pink hue, blemished with ruddy patches. Where its face should be, there is nothing more than a sunken cavern, as if a stone giant's fist made an impression in the creature's head, crushing all of its features and leaving nothing but a gaping black void. Its arms are elongated, and instead of hands, it has scythe-shaped blades of bone and flesh. Its legs seem to be twisted, causing it to walk with an awkward gait.", attacks = { { type = "dual_armrake" } }, spells = { "Limb Disruption", "Wither" }, abilities = { "tremors", "hamstring" } },

    -- Level 107
    { template_id = "ashen_patrician_vampire", name = "ashen patrician vampire", level = 107, spawn_areas = { "Moonsedge" }, roam_areas = { "Moonsedge" }, family = "humanoid", classification = "corporeal_undead", body_type = "biped", hp = 375, hp_variance = 37, ds_melee = 480, ds_bolt = 490, td = 544, udf = 530, armor_asg = 8, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "==Description== Sleek and sinuous, the patrician vampire cuts a lithe figure in fine court attire, her coat a tailor's masterwork adorned with glittering samite the color of moonglow. For all her finery, there is something otherworldly about her features: they are too fine and unsullied by blemishes, and there is an ashen pallor to her skin that cannot wholly be concealed by powder and paint. Thin white fangs peek from between her blanched lips, giving her the appearance of being on the edge of a knowing smirk. Appraisal: The patrician vampire is medium in size and about six feet high in her current state.", attacks = { { type = "rapier" } }, spells = { "Blind" }, abilities = { "disarm_weapon", "taunt", "blink_1215" } },
    { template_id = "gigantic_lightning_whelk", base_template = "war_griffin", name = "gigantic lightning whelk", level = 107, spawn_areas = { "Moghreb Jungle", "Singing Crags" }, roam_areas = { "Moghreb Jungle", "Singing Crags" }, family = "whelk", body_type = "hybrid", preferred_stance = "forward", stance_profile = "berserker", description = "==Hunting Strategies== *" },
    { template_id = "quivering_sanguine_ooze", base_template = "war_griffin", name = "quivering sanguine ooze", level = 107, spawn_areas = { "Hinterwilds" }, roam_areas = { "Hinterwilds" }, family = "ooze", body_type = "hybrid", preferred_stance = "forward", stance_profile = "berserker", description = "A quivering sanguine ooze is a vast blob of partially coagulated goop that wobbles and squelches its way across the ground, leaving behind a sticky crimson trail. Suspended within is a constellation of detritus and bones, some still with flesh attached. Dripping pseudopods test the air, suggesting that the ooze bears at least rudimentary intelligence, though hopefully not enough to consider its abominable state." },
    { template_id = "scaly_needle_toothed_trenchling", base_template = "war_griffin", name = "scaly needle-toothed trenchling", level = 107, spawn_areas = { "Moghreb Jungle", "Seat of Storms" }, roam_areas = { "Moghreb Jungle", "Seat of Storms" }, family = "trenchling", body_type = "hybrid", preferred_stance = "forward", stance_profile = "berserker", description = "==Hunting Strategies== *" },

    -- Level 108
    { template_id = "garish_revenant_buccaneer", base_template = "deathsworn_fanatic", name = "garish revenant buccaneer", level = 108, spawn_areas = { "Ship Graveyard" }, roam_areas = { "Ship Graveyard" }, family = "humanoid", body_type = "hybrid", preferred_stance = "guarded", stance_profile = "caster", description = "==Hunting Strategies== *" },
    { template_id = "sleek_black_kiramon_stalker", name = "sleek black kiramon stalker", level = 108, spawn_areas = { "The Hive" }, roam_areas = { "The Hive" }, family = "kiramon", body_type = "insectoid", hp = 325, hp_variance = 32, armor_asg = 12, armor_natural = true, preferred_stance = "offensive", stance_profile = "skirmisher", description = "Glittering, spherical eyes stand out from the matte black of the kiramon stalker's carapace, which is so dark that it seems to drink the surrounding light. The stalker is a creature seemingly tailored for speed and stealth. Roughly shaped like a mantis, it balances on stick-like legs with powerful hindquarters, and it looks ever ready to spring. Wings like gossamer shadows enfold the stalker's thorax like a dusky cloak.", attacks = { { type = "claw" }, { type = "stinger_attack" } } },
    { template_id = "vvrael_destroyer", base_template = "vvrael_witch", name = "vvrael destroyer", level = 108, spawn_areas = { "Scatter" }, roam_areas = { "Scatter" }, family = "vvrael", classification = "extra_planar", body_type = "biped", ds_ranged = 375, armor_asg = 20, armor_natural = false, preferred_stance = "guarded", stance_profile = "caster", description = "A 'Vvrael destroyer' can be found in the Scatter in the Rift. This is a greater servant of the Vvrael, sent to dispatch the strongest of their foes. These are warrior type creatures . A strong jawline and shrewd, narrowed eyes are prominent in the features of the Vvrael destroyer's countenance, creating of his mouth a severe line and of his gaze an openly vicious stare. All the malice caught in the creature's eyes make promises to be answered by the muscular, though ephemeral physique obvious even below his segmented pieces of armor. Despite the bulk of his form, the destroyer moves with the militant grace of a seasoned warrior, precise and purposeful.", attacks = { { type = "claidhmore" }, { type = "maul" } }, abilities = { "tackle" } },
    { template_id = "withered_shadow_cloaked_draugr", base_template = "patchwork_flesh_monstrosity", name = "withered shadow-cloaked draugr", level = 108, spawn_areas = { "Hinterwilds" }, roam_areas = { "Hinterwilds" }, family = "gigas", classification = "corporeal_undead", body_type = "biped", armor_asg = 7, armor_natural = false, preferred_stance = "forward", stance_profile = "berserker", description = "Utterly immense, the draugr's humanoid shape is comprised wholly of inky shadows that drip and pool at its intangible feet. Cruel eyes of frigid light glare from a face of sharp lines and malevolent angles. The shade's arms are lightless and devoid of all but the most rudimentary features, but are massively thick and traced with intricate lines of blazing blue radiance. A 'shadow-cloaked draugr' is a type of corporeal undead creature, approximately level 105-110, found in the Pits of the Dead zone of the Hinterwilds. They are enormous, powerful creatures typically wielding a two-handed greatsword with tremendous strength, but also capable of various maneuver attacks able to damage and knock players prone. They wear decaying leathers that are equivalent to AsG 7 armor (reinforced leather). {{TOC limit|3}}", attacks = { { type = "greatsword" } } },

    -- Level 109
    { template_id = "fulminating_stormborn_primordial", base_template = "crackling_lightning_fiend", name = "fulminating stormborn primordial", level = 109, spawn_areas = { "Moghreb Jungle", "Singing Crags" }, roam_areas = { "Moghreb Jungle", "Singing Crags" }, family = "elemental", body_type = "hybrid", preferred_stance = "guarded", stance_profile = "caster", description = "==Hunting Strategies== * Electricity discharges down the length of the somnis spiked mace! ... 1 point of damage! Light shock to left arm. That stings! Chance to receive lightning damage when striking the primordial with a melee weapon.", spells = { "Elemental Strike" }, abilities = { "call_wind", "tremors" } },
    { template_id = "kelp_tangled_coral_golem", base_template = "night_golem", name = "kelp-tangled coral golem", level = 109, spawn_areas = { "Moghreb Jungle", "Seat of Storms" }, roam_areas = { "Moghreb Jungle", "Seat of Storms" }, family = "golem", body_type = "biped", preferred_stance = "forward", stance_profile = "berserker", immune = { "puncture" } },
    { template_id = "squamous_reptilian_mutant", base_template = "sand_devil", name = "squamous reptilian mutant", level = 109, spawn_areas = { "Hinterwilds" }, roam_areas = { "Hinterwilds" }, family = "reptilian", body_type = "hybrid", td = 496, preferred_stance = "guarded", stance_profile = "caster", description = "Clad in thick, pooling garb that conceals the worst of her tortured form, the mutant was once a being of great stature. Now her body is hunched and bent beneath the weight of her transformation. Her skin sloughs in places, revealing scaling reminiscent of a lizard's, the lamina pale but faintly tinged with cold color. The monstrous alterations to the mutant's form have not spared her features. They are an uneven mass of tumorous growths and molting, squamous skin into which two slit-pupiled eyes of monstrous golden hue are deeply set. Pronounced venom sacs, far from symmetrical, bulge from the sides of the mutant's neck as if to match the uneven distension of her cranium.", attacks = { { type = "cudgel" } }, spells = { "Bind" } },

    -- Level 110
    { template_id = "lich", base_template = "monastic_lich", name = "lich", level = 110, spawn_areas = { "Scatter" }, roam_areas = { "Scatter" }, family = "humanoid", classification = "corporeal_undead", body_type = "biped", ds_melee = 661, ds_bolt = 550, td = 493, preferred_stance = "guarded", stance_profile = "caster", description = "{{Otheruses4|the creature found in the Rift|the scripting engine|Lich (software)}} A 'Lich' can be found in the Scatter in the Rift. This is a highly intelligent spell caster who went to great lengths to gain power and longevity, at the cost of his soul. Liches can spawn as 'frostborne' or 'infernal', depending on the temperature of the Scatter at the time.", attacks = { { type = "runestaff" } }, spells = { "Cold Snap", "Dark Catalyst", "Elemental Disjunction" }, abilities = { "cold_flare", "tremors" } },
    { template_id = "lithe_black_abyranra", base_template = "war_griffin", name = "lithe black abyran'ra", level = 110, spawn_areas = { "Old Ta'Faendryl" }, roam_areas = { "Old Ta'Faendryl" }, family = "demon", body_type = "hybrid", preferred_stance = "forward", stance_profile = "berserker", description = "A wreath of thirteen black serpents ring the 'abyran'ras head, bestowing it a full crown of the twisting vipers as they writhe back and forth in an undulating, hypnotic fashion. Its pale, lidless eyes are devoid of pupils -- merely rippling with faint hints of color every few moments. Twin pairs of fangs peek out from beneath its thin lips, and the smoothness of its skin fades away into sleek scales below its abdomen, its lower body tapering into a massive, sinuous tail like that of a snake's. Its elongated, spindly fingers end in scythe-like black talons, their razored edges gleaming with the faintest light as they weave sinuous patterns in swift, slicing arcs." },
    { template_id = "roiling_crimson_angargeist", base_template = "war_griffin", name = "roiling crimson angargeist", level = 110, spawn_areas = { "Hinterwilds" }, roam_areas = { "Hinterwilds" }, body_type = "hybrid", ds_bolt = 510, td = 541, preferred_stance = "forward", stance_profile = "berserker", description = "Swirling ectoplasm, crimson and black and lit from within by crackles of sickly yellow energy, takes on a rough humanoid shape, but the angargeist is clearly nothing alive. Where a face ought to be is a molten ruin, lopsided eyes of unholy flame sparking in its ill-made sockets. Immaterial and dripping essence, the arms and legs are uneven, both ending in straining talons. The angargeist's form bubbles and simmers in places like fury lent form." },
    { template_id = "tenebrific_wraith_shark", base_template = "mist_wraith", name = "tenebrific wraith shark", level = 110, spawn_areas = { "Ship Graveyard" }, roam_areas = { "Ship Graveyard" }, family = "wraith", classification = "non_corporeal_undead", body_type = "hybrid", preferred_stance = "offensive", stance_profile = "skirmisher", description = "==Hunting Strategies== *" },
    { template_id = "translucent_kiramon_strandweaver", base_template = "kiramon_worker", name = "translucent kiramon strandweaver", level = 110, spawn_areas = { "The Hive" }, roam_areas = { "The Hive" }, family = "kiramon", body_type = "insectoid", hp = 325, hp_variance = 32, armor_asg = 1, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "Glistening as if moist, the carapace of the kiramon strandweaver is ghost-pale and translucent in places, revealing pulsating organs and fluid-filled sacs quivering beneath. The strandweaver is around the size of a halfling, her undersized body supported by six segmented legs. Her abdomen tapers toward a pair of spinnerets aglisten with prismatic threads of spent webbing.", spells = { "Empathic Link" }, abilities = { "web_immobilize" } },

    -- Level 111
    { template_id = "blubbery_humpbacked_merrow", base_template = "war_griffin", name = "blubbery humpbacked merrow", level = 111, spawn_areas = { "Ship Graveyard", "Seat of Storms" }, roam_areas = { "Ship Graveyard", "Seat of Storms" }, family = "merrow", body_type = "hybrid", preferred_stance = "forward", stance_profile = "berserker", description = "==Hunting Strategies== *Merrows have a passive spell dissipating ability that seems to absorb one spell cast at them. You utter a light chant and raise your hands, beckoning the lesser spirits to aid you with the Web spell... Your spell is ready. You gesture at a blubbery humpbacked merrow. Your spell meets a blubbery humpbacked merrow's scaled hide and dissipates into raw mana, untangling into hissing threads of of dying radiance. You utter a light chant and raise your hands, beckoning the lesser spirits to aid you with the Web spell... Your spell is ready. You gesture at a blubbery humpbacked merrow. Cloudy wisps swirl about a blubbery humpbacked merrow. [SMR result: 192 (Open d100: 83, Bonus: 56)] The wisps solidify into thick strands of webbing that tighten about her body! A blubbery humpbacked merrow becomes ensnared in thick strands of webbing!" },
    { template_id = "colossal_boreal_undansormr", base_template = "cave_worm", name = "colossal boreal undansormr", level = 111, spawn_areas = { "Hinterwilds" }, roam_areas = { "Hinterwilds" }, family = "worm", body_type = "ophidian", td = 572, preferred_stance = "offensive", stance_profile = "skirmisher", description = "Gleaming scales protect the vermiform body of a colossal boreal undansormr. Most of the undansormr's natural armor is of cinereous hue, but there are occasional glints of striking teal or shocking blue, especially along the creature's raised spine. the undansormr's visage boasts a trio of glowing amber eyes. The two smaller ones are laterally placed, while the largest dominates the center of the undansormr's serpentine head. More eyes dot the sinuous length of the beast, though with less regular configuration and sizing." },
    { template_id = "grey_plumed_steelwing_harpy", base_template = "plumed_cockatrice", name = "grey-plumed steelwing harpy", level = 111, spawn_areas = { "Singing Crags" }, roam_areas = { "Singing Crags" }, family = "harpy", body_type = "hybrid", preferred_stance = "offensive", stance_profile = "skirmisher", description = "==Hunting Strategies== *" },

    -- Level 112
    { template_id = "bloated_kiramon_broodtender", base_template = "kiramon_worker", name = "bloated kiramon broodtender", level = 112, spawn_areas = { "The Hive" }, roam_areas = { "The Hive" }, family = "kiramon", body_type = "insectoid", hp = 500, hp_variance = 50, armor_asg = 14, armor_natural = true, preferred_stance = "guarded", stance_profile = "caster", description = "Possessed of a small, glossy black head with a long proboscis, the kiramon broodtender would be comical in shape were it not so grotesque. Most of its abdomen is bloated, gelatinous, and yielding. Riotous colors ooze across flesh like the surface hues of an oil slick. Eight glinting black eyes stare from her undersized head, nestled amidst a thicket of coarse hairs. Wrapped around the monstrosity's abdomen are a number of gooey sensory tendrils." },
    { template_id = "eyeless_black_valravn", base_template = "firebird", name = "eyeless black valravn", level = 112, spawn_areas = { "Hinterwilds" }, roam_areas = { "Hinterwilds" }, family = "bird", classification = "corporeal_undead", body_type = "avian", td = 527, armor_asg = 1, armor_natural = false, preferred_stance = "offensive", stance_profile = "skirmisher", description = "Wings of stygian darkness enshroud the huge black bird. When not in motion, there is an ominous and unnatural stillness to the valravn that marks it as otherworldly. Where eyes should be, there are strange hollows that occasionally flicker with scintillating golden light." },
    { template_id = "pallid_fog_cloaked_kelpie", base_template = "siren", name = "pallid fog-cloaked kelpie", level = 112, spawn_areas = { "Ship Graveyard" }, roam_areas = { "Ship Graveyard" }, family = "equine", body_type = "hybrid", preferred_stance = "guarded", stance_profile = "caster", description = "==Hunting Strategies== *", spells = { "Elemental Strike", "Elemental Disjunction" }, abilities = { "cold_flare", "tremors" } },

    -- Level 113
    { template_id = "amaranthine_kraken_tentacle", base_template = "war_griffin", name = "amaranthine kraken tentacle", level = 113, spawn_areas = { "Ship Graveyard" }, roam_areas = { "Ship Graveyard" }, family = "kraken", body_type = "hybrid", preferred_stance = "forward", stance_profile = "berserker", description = "==Hunting Strategies== *" },
    { template_id = "flayed_gigas_disciple", base_template = "triton_fanatic", name = "flayed gigas disciple", level = 113, spawn_areas = { "Hinterwilds" }, roam_areas = { "Hinterwilds" }, family = "gigas", body_type = "biped", td = 525, preferred_stance = "guarded", stance_profile = "caster", description = "A flayed gigas disciple is a hugely imposing figure. His monumental physique is all the more evident because his skin has been torn away, revealing wet and weeping tendons and raw muscle beneath. With no lips to conceal his teeth, the disciple appears to be ever grinning, but above his ruined nose are scarlet eyes ablaze with hateful zeal. A flayed gigas disciple wears a hooded shroud, ragged and threadbare, that is stained through with his own blood.", spells = { "903", "1115", "719" } },

    -- Level 114
    { template_id = "shining_winged_disir", base_template = "farlook", name = "shining winged disir", level = 114, spawn_areas = { "Hinterwilds" }, roam_areas = { "Hinterwilds" }, body_type = "hybrid", preferred_stance = "guarded", stance_profile = "caster", description = "Clad from head to toe in armor of shining gold, the disir takes the form of a powerfully built woman with ageless features and eyes like pools of sunlit sky. On her head, nestled atop curls of shimmering hair, is a winged helm whose visor dips low over her face, lending a grim cast to her features. The disir's skin is faintly luminous, with hints of rainbowed color pulsing beneath it.", attacks = { { type = "lance" } }, spells = { "Censure" } },

    -- Level 115
    { template_id = "algae_draped_merrow_oracle", base_template = "triton_brawler", name = "algae-draped merrow oracle", level = 115, spawn_areas = { "Seat of Storms" }, roam_areas = { "Seat of Storms" }, family = "merrow", body_type = "biped", armor_asg = 2, armor_natural = false, preferred_stance = "forward", stance_profile = "berserker" },

    -- Level 120
    { template_id = "cinereous_chthonian_sybil", base_template = "farlook", name = "cinereous chthonian sybil", level = 120, spawn_areas = { "Hinterwilds" }, roam_areas = { "Hinterwilds" }, body_type = "hybrid", preferred_stance = "guarded", stance_profile = "caster", description = "Draped by diaphanous silks that appear so light as to have been woven from shreds of evening mist, a cinereous chthonian sybil is a thin, almost skeletal figure. Wings with iridescent grey feathers enshroud her form. Her face is unsettling in its agelessness, and her eyes are nothing human. They are two pools of luminous mist, and in their depths flit strange shapes and half-formed figures that are at once tantalizingly familiar and distressingly vague.", spells = { "Astral Spear", "Dark Catalyst", "Mindwipe", "Condemn", "Meteor Swarm" }, abilities = { "blink_1215" } },
    { template_id = "silver_scaled_cold_wyrm", base_template = "firebird", name = "silver-scaled cold wyrm", level = 120, spawn_areas = { "Hinterwilds" }, roam_areas = { "Hinterwilds" }, family = "reptilian", body_type = "avian", preferred_stance = "guarded", stance_profile = "caster", description = "Resplendent scales of royal blue brighter than cut gemstones form nigh-impregnable armor over the cold wyrm's sinuous form, sheened with iridescent silver that leavens the intensity of their hue. For all her preternatural beauty, there is a cruel cast to the wyrm's visage. Her snout is tapered and full of serrated teeth, and her predatory amber eyes have slitted pupils. A frill of spines frames the wyrm's head, bright with bands of silver that glint threateningly in the ambient light. Two vast wings branch from the wyrm's shoulders, membranous and paler than the rest of her body, immensely sized to hold the wyrm aloft when riding on currents of air. {{TOC limit|2}}", attacks = { { type = "bite" }, { type = "claw" }, { type = "tail_swing" }, { type = "dive" } }, spells = { "Sympathy" } },
}

return Catalog
